package com.guhflix.shell
import org.json.JSONArray
import org.junit.Assert.*
import org.junit.Test
class FamilyProfilesTest {
 private fun reject(f:()->Unit){try{f();fail("Expected rejection")}catch(_:IllegalArgumentException){}}
 @Test fun peopleSurviveRestartAndCanBeSelectedWithoutPassword(){var disk:String?=null;val s=FamilyProfiles({disk},{disk=it});s.create("Ana",2);s.create("Bruno",3);val ids=(0..1).map{s.list().getJSONArray("items").getJSONObject(it).getString("id")};assertNotEquals(ids[0],ids[1]);s.select(ids[0]);val reopened=FamilyProfiles({disk},{disk=it});assertNull(reopened.activeId());assertEquals("Bruno",reopened.select(ids[1]).getString("name"));assertEquals("Ana",reopened.select(ids[0]).getString("name"))}
 @Test fun oldPinsAreRemovedWithoutChangingLibraryIdentity(){var disk:String?="""[{"id":"old-profile-id","name":"Mãe","avatar":2,"hash":"fixture-only-old-hash","salt":"fixture-only-old-salt"}]""";val s=FamilyProfiles({disk},{disk=it});val p=s.list().getJSONArray("items").getJSONObject(0);assertEquals("old-profile-id",p.getString("id"));assertFalse(disk!!.contains("hash"));assertFalse(disk!!.contains("salt"));assertFalse(p.has("locked"));assertEquals("Mãe",s.select("old-profile-id").getString("name"));s.update("old-profile-id","Mamãe",5);assertEquals("old-profile-id",s.list().getJSONArray("items").getJSONObject(0).getString("id"))}
 @Test fun validationAndCapacityStillApply(){var disk:String?=null;val s=FamilyProfiles({disk},{disk=it});reject{s.create(" ",0)};repeat(6){s.create("Perfil $it",it)};reject{s.create("Sétimo",0)};val ids=(0..5).map{s.list().getJSONArray("items").getJSONObject(it).getString("id")};assertEquals(6,ids.toSet().size);reject{s.update(ids[0],"",1)}}
 @Test fun managingOnePersonDoesNotSwitchOrDeleteAnother(){var disk:String?=null;val s=FamilyProfiles({disk},{disk=it});s.create("Ana",0);s.create("Bruno",1);val a=s.list().getJSONArray("items").getJSONObject(0).getString("id");val b=s.list().getJSONArray("items").getJSONObject(1).getString("id");s.select(b);s.update(a,"Ana Maria",4);assertEquals(b,s.activeId());s.delete(a);assertEquals(b,s.activeId());assertEquals("Bruno",s.list().getJSONArray("items").getJSONObject(0).getString("name"));s.delete(b);assertNull(s.activeId());assertEquals(0,JSONArray(disk).length())}
 @Test fun profileCanBeEditedBeforeEnteringAndFailedSaveIsNotSilentlyAccepted(){var disk:String?=null;val s=FamilyProfiles({disk},{disk=it});s.create("Ana",0);val id=s.list().getJSONArray("items").getJSONObject(0).getString("id");s.lock();s.update(id,"Ana Maria",1);assertNull(s.activeId());assertEquals("Ana Maria",s.select(id).getString("name"));val broken=FamilyProfiles({disk},{throw IllegalStateException("storage unavailable")});try{broken.create("Bruno",2);fail()}catch(_:IllegalStateException){};assertEquals(1,s.list().getJSONArray("items").length())}
 @Test fun allTwelveAvatarChoicesAndChildFlagPersistWithoutChangingProfileId(){var disk:String?=null;val p=FamilyProfiles({disk},{disk=it});p.create("Pessoa",11,true);val id=p.list().getJSONArray("items").getJSONObject(0).getString("id");for(avatar in 0..11){p.update(id,"Pessoa",avatar,true);val reopened=FamilyProfiles({disk},{disk=it});val row=reopened.select(id);assertEquals(avatar,row.getInt("avatar"));assertTrue(row.getBoolean("kids"));assertEquals(id,row.getString("id"))}}
}
